package org.transittr;
import android.app.*;import android.appwidget.*;import android.content.*;import android.net.Uri;import android.os.*;import android.view.View;import android.widget.*;import java.util.*;import java.text.*;import org.json.*;
/** API 8 RemoteViews widget: two visible favourites, no collection service or map. */
public final class TransitWidget extends AppWidgetProvider {
 public static final String REFRESH="org.transittr.widget.REFRESH",NEXT="org.transittr.widget.NEXT",TICK="org.transittr.widget.TICK",OPEN="org.transittr.widget.OPEN";
 public static int resource(Context c,String type,String name){return c.getResources().getIdentifier(name,type,c.getPackageName());}
 public static int[] ids(Context c){return AppWidgetManager.getInstance(c).getAppWidgetIds(new ComponentName(c,TransitWidget.class));}
 private static int flags(){return PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=23?0x04000000:0);}
 private static PendingIntent action(Context c,String action,int id){Intent i=new Intent(c,TransitWidget.class).setAction(action).setData(Uri.parse("transittr://widget/"+id+"/"+action));i.putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);return PendingIntent.getBroadcast(c,id,i,flags());}
 private static PendingIntent setup(Context c,int id){Intent i=new Intent(c,WidgetSetupActivity.class).setData(Uri.parse("transittr://widget/setup/"+id));return PendingIntent.getActivity(c,id,i,flags());}
 public static Intent open(Context c,WidgetFavorites.Entry e){return new Intent(c,TransitActivity.class).setAction(OPEN).setData(Uri.parse("transittr://favorite/"+e.id)).putExtra("favorite",e.id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);}
 public static int height(Context c,int id){if(Build.VERSION.SDK_INT<16)return 150;try{Bundle options=(Bundle)AppWidgetManager.class.getMethod("getAppWidgetOptions",Integer.TYPE).invoke(AppWidgetManager.getInstance(c),id);int low=options.getInt("appWidgetMinHeight",150),high=options.getInt("appWidgetMaxHeight",low);return c.getResources().getConfiguration().orientation==1?Math.max(low,high):low;}catch(Exception e){return 150;}}
 public static int capacity(Context c,int id){int h=height(c,id);return h<140?1:h>=220?3:2;}
 public static ArrayList<WidgetFavorites.Entry> visible(Context c,int id){ArrayList<WidgetFavorites.Entry> entries=WidgetFavorites.all(c),result=new ArrayList<WidgetFavorites.Entry>();int count=capacity(c,id),pages=Math.max(1,(entries.size()+count-1)/count),page=WidgetFavorites.state(c).getInt("page:"+id,0)%pages;for(int i=page*count;i<Math.min(entries.size(),page*count+count);i++)result.add(entries.get(i));return result;}
 public static void renderAll(Context c){for(int id:ids(c))render(c,id);}
 public static void render(Context c,int id){RemoteViews views=views(c,id);AppWidgetManager.getInstance(c).updateAppWidget(id,views);}
 public static RemoteViews views(Context c,int id){ThemeColors theme=ThemeColors.of(c);boolean compact=capacity(c,id)==1;RemoteViews v=new RemoteViews(c.getPackageName(),resource(c,"layout",(compact?"transit_widget_small":"transit_widget")+(theme.dark?"_dark":"")));ArrayList<WidgetFavorites.Entry> all=WidgetFavorites.all(c),entries=visible(c,id);int count=capacity(c,id),pages=Math.max(1,(all.size()+count-1)/count),page=WidgetFavorites.state(c).getInt("page:"+id,0)%pages;if(!compact)v.setTextViewText(resource(c,"id","widget_page"),(page+1)+" / "+pages);else v.setTextViewText(resource(c,"id","widget_next"),(page+1)+"/"+pages+" ›");v.setOnClickPendingIntent(resource(c,"id","widget_next"),action(c,NEXT,id));v.setOnClickPendingIntent(resource(c,"id","widget_refresh"),action(c,REFRESH,id));if(compact)v.setOnClickPendingIntent(resource(c,"id","widget_stop0"),setup(c,id));if(!compact){v.setOnClickPendingIntent(resource(c,"id","widget_setup"),setup(c,id));v.setOnClickPendingIntent(resource(c,"id","widget_title"),setup(c,id));}v.setViewVisibility(resource(c,"id","widget_empty"),entries.isEmpty()?View.VISIBLE:View.GONE);v.setOnClickPendingIntent(resource(c,"id","widget_empty"),setup(c,id));boolean busy=WidgetUpdateService.running||WidgetFavorites.state(c).getLong("busyUntil",0)>System.currentTimeMillis();v.setTextViewText(resource(c,"id","widget_refresh"),compact?(busy?"…":"↻"):(busy?"Alınıyor…":"Yenile"));SimpleDateFormat time=new SimpleDateFormat("HH:mm",Locale.US);time.setTimeZone(TimeZone.getTimeZone("GMT+03:00"));
  for(int i=0;i<(compact?1:3);i++){int row=resource(c,"id","widget_row"+i);v.setViewVisibility(row,i<entries.size()?View.VISIBLE:View.GONE);if(i>=entries.size())continue;WidgetFavorites.Entry e=entries.get(i);JSONObject data=WidgetFavorites.result(c,e.id);long at=data.optLong("at",0);boolean old=at>0&&(System.currentTimeMillis()-at>120000||data.optBoolean("error"));String label=(e.label.length()>0?e.label:WidgetFavorites.cityName(e.city))+" · "+e.stop+(e.direction.length()>0?" · "+(e.direction.equals("G")?"Gidiş":"Dönüş"):"");String stamp=at>0?(old?"Eski · ":"")+time.format(new Date(at)):data.optBoolean("error")?"Bağlantı yok":"Henüz sorgulanmadı";v.setTextViewText(resource(c,"id","widget_line"+i),e.line);v.setTextViewText(resource(c,"id","widget_stop"+i),label);v.setTextViewText(resource(c,"id","widget_eta"+i),data.optString("eta","—"));v.setTextViewText(resource(c,"id","widget_stamp"+i),stamp);v.setTextColor(resource(c,"id","widget_eta"+i),old?theme.muted:theme.ink);v.setOnClickPendingIntent(row,PendingIntent.getActivity(c,e.id.hashCode(),open(c,e),flags()));}
  return v;
 }
 public static void request(Context c){renderAll(c);if(ids(c).length==0)return;if(WidgetFavorites.all(c).isEmpty()){schedule(c);return;}if(WidgetUpdateService.running||WidgetFavorites.state(c).getLong("busyUntil",0)>System.currentTimeMillis()){schedule(c);return;}try{if(Build.VERSION.SDK_INT>=26){try{Class.forName("org.transittr.WidgetJobService").getMethod("schedule",Context.class).invoke(null,c);}catch(ClassNotFoundException legacy){c.startService(new Intent(c,WidgetUpdateService.class));}schedule(c);return;}c.startService(new Intent(c,WidgetUpdateService.class));}catch(Exception e){WidgetFavorites.state(c).edit().putLong("busyUntil",0).commit();renderAll(c);}schedule(c);}
 public static void schedule(Context c){AlarmManager alarm=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);PendingIntent tick=action(c,TICK,-1);if(ids(c).length==0||WidgetFavorites.all(c).isEmpty()){alarm.cancel(tick);return;}alarm.set(AlarmManager.RTC,System.currentTimeMillis()+60000,tick);}
 public void onUpdate(Context c,AppWidgetManager manager,int[] ids){for(int id:ids)render(c,id);request(c);}
 public void onAppWidgetOptionsChanged(Context c,AppWidgetManager manager,int id,Bundle options){render(c,id);request(c);}
 public void onDeleted(Context c,int[] ids){for(int id:ids)WidgetFavorites.state(c).edit().remove("page:"+id).commit();schedule(c);}
 public void onDisabled(Context c){schedule(c);}
 public void onReceive(Context c,Intent i){String action=i.getAction();if(REFRESH.equals(action)){request(c);return;}if(NEXT.equals(action)){int id=i.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);boolean owned=false;for(int x:ids(c))if(x==id)owned=true;if(!owned)return;int count=capacity(c,id),pages=Math.max(1,(WidgetFavorites.all(c).size()+count-1)/count),page=WidgetFavorites.state(c).getInt("page:"+id,0);WidgetFavorites.state(c).edit().putInt("page:"+id,(page+1)%pages).commit();render(c,id);request(c);return;}if(TICK.equals(action)){PowerManager power=(PowerManager)c.getSystemService(Context.POWER_SERVICE);if(power.isScreenOn())request(c);else schedule(c);return;}super.onReceive(c,i);}
}
